# The old updates address has a direct chronological purpose.
write('research','Latest SIR developments','The latest developments covered here, listed in date order.', '<header class="article-top"><p class="eyebrow">OCTOBER 2026</p><h1>The latest developments covered here.</h1><p class="lede">Read these after the <a href="../index.html">full chronological story</a>.</p></header><article class="prose">'+''.join(f'<section class="timeline-item"><time>{E(date)}</time><h2>{E(title)}</h2><p>{E(text)}</p></section>' for date,title,text in rows if 'Oct 2026' in date)+'</article>')
